mapper.select:
select
id, cell_sha256_code_list, package_id
from b_xiecheng_colliding_data_loop_cycle
where is_delete = 0 and retry_count = 0
 and release_time > #{startDate} and release_time < #{endDate}

    and id > #{minId}

order by id limit #{pageSize};

select id, cell_sha256_code_list, package_id from b_xiecheng_colliding_data_loop_cycle where is_delete = 0
and retry_count = 3
and retry_count > 0 and retry_count < 3
and id > #{minId}
order by id asc limit #{pageSize};

select
    *
from b_xiecheng_colliding_data_loop_cycle
where is_delete = 1
     and push_time < #{startTime}
limit #{size};

