mapper.select:
select bmc.cid as cid, bmc.api_code as apiCode, bmc.short_name as shortName, '-' as packageName, '-' as discreetNumber, count(dlc.id) AS remainingNumber, '0' as collidingSwitch, '0' as priority, count(dlc.id) as collidingBackNumber, min(dlc.release_time) as collidingStartTime, max(dlc.release_time) as collidingEndTime from b_xiecheng_colliding_data_loop_cycle dlc left join b_marketing_customer bmc on bmc.status = 1 where dlc.is_delete = 0
and bmc.api_code = #{listParam.apiCode}
AND dlc.release_time BETWEEN #{listParam.collidingStartTime} AND #{listParam.collidingEndTime}
GROUP BY DATE_FORMAT(dlc.release_time, '%Y-%m-%d') ORDER BY DATE_FORMAT(dlc.release_time, '%Y-%m-%d')

select a.id from b_xiecheng_colliding_data_loop_cycle a left join ( ${queryRuleScoreDataSql} ) b on a.cell_sha256_code_list = b.cell where a.is_delete = 0 and b.id is null and a.release_time >= DATE_ADD(CURDATE(), INTERVAL 1 DAY) and a.release_time < DATE_ADD(CURDATE(), INTERVAL 7 DAY)
and a.id > #{minId}
order by a.id limit 2000;

